"""The pydata CLI: analyze a CSV → summary stats on stdout + a PNG plot.

Deliberately tiny and honest: pandas does the table work, matplotlib
(Agg — never a display) renders, numpy rides under both. Everything the
command touches comes from the payload's mounted image.
"""

import argparse
import os
import sys

import matplotlib

matplotlib.use("Agg")  # headless by construction — before pyplot imports
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402

from pydata_toolkit import __version__  # noqa: E402

# The bundled sample table — read __file__-relative from inside the
# mounted image (conformance arm 2). os.path stays lexical: no realpath
# re-rooting, the driver already hands absolute VFS paths.
BUNDLED_CSV = os.path.join(os.path.dirname(__file__), "data", "rivers.csv")


def _numeric_columns(frame):
    return [c for c in frame.columns if pd.api.types.is_numeric_dtype(frame[c])]


def analyze(csv_path, out_path):
    """Read CSV → print summary stats → render a PNG of the numeric series."""
    frame = pd.read_csv(csv_path)
    numeric = _numeric_columns(frame)
    if not numeric:
        sys.stderr.write("pydata: %s carries no numeric columns to analyze\n" % csv_path)
        return 65

    print("pydata analyze: %s" % csv_path)
    print("rows: %d  columns: %d (%s)" % (len(frame), len(frame.columns), ", ".join(frame.columns)))
    print()
    print(frame[numeric].describe().to_string())
    print()

    fig, ax = plt.subplots(figsize=(8, 4.5))
    x = np.arange(len(frame))
    for column in numeric:
        ax.plot(x, frame[column].to_numpy(dtype=float), marker="o", label=column)
    ax.set_xlabel("row")
    ax.set_title(os.path.basename(csv_path))
    ax.legend()
    ax.grid(True, alpha=0.3)
    fig.tight_layout()
    fig.savefig(out_path, dpi=110)
    plt.close(fig)
    print("plot: %s (%d bytes)" % (out_path, os.path.getsize(out_path)))
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="pydata",
        description="the curated tebako python data-science toolkit (numpy %s / pandas %s / matplotlib %s)"
        % (np.__version__, pd.__version__, matplotlib.__version__),
    )
    parser.add_argument("--version", action="version", version="pydata %s" % __version__)
    sub = parser.add_subparsers(dest="command")

    p_analyze = sub.add_parser("analyze", help="summarize a CSV and render a PNG plot")
    p_analyze.add_argument("csv", help="the CSV table to analyze")
    p_analyze.add_argument("--out", default="pydata-plot.png", help="the PNG output path")

    p_demo = sub.add_parser("demo", help="analyze the bundled sample table (read __file__-relative)")
    p_demo.add_argument("--out", default="pydata-demo.png", help="the PNG output path")

    args = parser.parse_args(argv)
    if args.command == "analyze":
        return analyze(args.csv, args.out)
    if args.command == "demo":
        return analyze(BUNDLED_CSV, args.out)
    parser.print_help()
    return 2
